import{_ as t,o,c as n,O as s}from"./chunks/framework.2c2d5a61.js";const h=JSON.parse('{"title":"Java 基础","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/01-Java基础.md","filePath":"interview/后端/Java/01-Java基础.md","lastUpdated":1789026500000}'),g={name:"interview/后端/Java/01-Java基础.md"};function a(e,r,i,l,p,c){return o(),n("div",null,r[0]||(r[0]=[s('<h1 id="java-基础" tabindex="-1">Java 基础 <a class="header-anchor" href="#java-基础" aria-label="Permalink to &quot;Java 基础&quot;">​</a></h1><blockquote><p><strong>怎么用这份笔记</strong></p><ul><li>分级：<code>★★★ 必须吃透</code> / <code>★★☆ 了解即可（记结论就行）</code> / <code>★☆☆ 可以跳过（一句话看一眼）</code></li><li>【简历亮点，高频追问】：简历里写过的技术，面试官会顺着往下挖，这段必须能展开讲</li><li>每个考点固定三段：<strong>通俗理解 → 我的项目关联 → 面试答题话术</strong></li><li>「我的项目关联」里的坑分两种，别搞混： <ul><li>写**「线上」**= 真实发生过的问题，可以直接讲现象和修复</li><li>写**「通用坑」<strong>= 经典坑 / 资料里学到的，我们项目没实际踩到，面试时</strong>别说成自己踩过**</li></ul></li></ul></blockquote><hr><h2 id="_1-与-equals、hashcode-契约-★★★" tabindex="-1">1. == 与 equals、hashCode 契约 ★★★ <a class="header-anchor" href="#_1-与-equals、hashcode-契约-★★★" aria-label="Permalink to &quot;1. == 与 equals、hashCode 契约 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><code>==</code> 问的是「是不是同一个东西」——<strong>基本类型</strong>比值，对象比<strong>地址</strong>。<code>equals</code> 默认也问地址，但 <strong>String</strong>、<strong>Integer</strong> 这些类把它改成了「内容一样就算相等」。<code>hashCode</code> 是给 <strong>HashMap</strong> 定位桶用的门牌号。<strong>契约</strong>一句话：两个对象 <strong>equals</strong> 相等，<strong>hashCode</strong> 必须相等。</p><p><strong>我的项目关联</strong><strong>设备会话</strong>、订单这类对象我们放在 <strong>Map</strong> / <strong>Set</strong> 里做<strong>去重</strong>和缓存，比如网关里按设备编号聚合的<strong>会话表</strong>。<strong>自定义对象</strong>只要会进集合，equals 和 hashCode 就成对<strong>重写</strong>，否则 Set 里能塞进重复对象、Map 里 get 不到。这条属于**「通用坑」**，我们项目没实际踩过，但一直是个硬规范。</p><p><strong>面试答题话术</strong> 「<code>==</code> 比的是地址或值，<code>equals</code> 默认也是比地址，只有 <strong>String</strong> 这类重写过的才是比值。核心<strong>契约</strong>是重写 equals 必须重写 hashCode，不然两个 equals 相等的对象 <strong>hashCode 不同</strong>，会落到<strong>不同桶</strong>，Set 能重复、Map get 不到。我项目里设备和订单对象会进 <strong>Map</strong> 做<strong>缓存</strong>，所以我的习惯是只要这个对象会进集合，这俩方法就成对重写。」</p><hr><h2 id="_2-string-不可变-常量池-stringbuilder-★★★" tabindex="-1">2. String 不可变 / 常量池 / StringBuilder ★★★ <a class="header-anchor" href="#_2-string-不可变-常量池-stringbuilder-★★★" aria-label="Permalink to &quot;2. String 不可变 / 常量池 / StringBuilder ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> String 创建后内容改不了，每次「修改」都是 new 一个新对象。好处是能<strong>安全共享</strong>、能当 <strong>HashMap</strong> 的 key（hash 不会变）。要频繁拼字符串就用 <strong>StringBuilder</strong>（快、线程不安全），多线程共享一个再考虑 <strong>StringBuffer</strong>。<strong>字符串常量池</strong>就是 String 的公共仓库，字面量直接复用。</p><p><strong>我的项目关联</strong> 网关拼装下发给充电桩的<strong>控制报文</strong>、拼装查询日志、互联互通拼签名原文，用的都是 <strong>StringBuilder</strong>。<strong>设备号</strong>、订单号这种<strong>高复用字符串</strong>天然吃到<strong>常量池</strong>的好处。这块属于常规用法，没有踩过坑。</p><p><strong>面试答题话术</strong> 「String <strong>不可变</strong>，所以能安全共享、能当 Map 的 key；代价是每次拼接都产生新对象，所以频繁拼接我用 <strong>StringBuilder</strong>。经典题 <code>new String(&quot;a&quot;)</code> 会产生<strong>两个对象</strong>，一个在<strong>常量池</strong>一个在堆，日常代码不会这么写。<strong>JDK9</strong> 之后 String 底层从 char 数组换成了 byte 数组，<strong>省一半空间</strong>，这个细节我答得出来但其实不影响用。」</p><hr><h2 id="_3-arraylist-linkedlist-扩容-★★★" tabindex="-1">3. ArrayList / LinkedList / 扩容 ★★★ <a class="header-anchor" href="#_3-arraylist-linkedlist-扩容-★★★" aria-label="Permalink to &quot;3. ArrayList / LinkedList / 扩容 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>ArrayList</strong> 就是一个能自动扩容的数组：按下标取元素快，中间插入删除慢（要挪后面的元素），满了自动扩到 <strong>1.5 倍</strong>。<strong>LinkedList</strong> 是双向链表，头尾操作快，但按下标找要一个个遍历，而且<strong>内存不连续</strong>、吃不到 <strong>CPU 缓存</strong>，所以实际用得非常少。</p><p><strong>我的项目关联</strong> 设备列表下发、订单批量处理、导出的数据集合都用 <strong>ArrayList</strong>，能预判大小的场景（比如按批次查出来的订单）我会给个<strong>初始容量</strong>，少扩几次容。<strong>LinkedList</strong> 项目里基本没出现过。 <strong>通用坑</strong>：for-each 里直接调 <code>list.remove()</code> 会抛 <strong>ConcurrentModificationException</strong>，得用 <code>iterator.remove()</code> 或者 <code>removeIf</code>。</p><p><strong>面试答题话术</strong> 「ArrayList 是数组，<strong>随机访问 O(1)</strong>，中间增删 <strong>O(n)</strong>，扩容 <strong>1.5 倍</strong>；LinkedList 是链表，头尾快但按下标找要遍历，而且<strong>内存不连续</strong>，实际性能经常还不如 ArrayList，所以项目里我基本只用 ArrayList。能预估大小的集合我会带<strong>初始容量</strong>，避免反复扩容。这个坑我是踩过的——遍历中直接 remove 会抛 <strong>ConcurrentModificationException</strong>，后来统一用 removeIf。」</p><hr><h2 id="_4-hashmap-底层原理-★★★" tabindex="-1">4. HashMap 底层原理 ★★★ <a class="header-anchor" href="#_4-hashmap-底层原理-★★★" aria-label="Permalink to &quot;4. HashMap 底层原理 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> HashMap = 「<strong>数组桶 + 链表/红黑树</strong>」。先用 key 的 hash 找到桶：桶是空的直接放，冲突了就挂成链表，链太长（<strong>8 个且数组 ≥ 64</strong>）转<strong>红黑树</strong>，把最坏查询从 <strong>O(n)</strong> 压到 <strong>O(logn)</strong>。容量固定取 <strong>2 的幂</strong>，这样能用<strong>位运算代替取模</strong>，而且扩容时只看多出来的那一位，不用重算 hash。<strong>负载因子 0.75</strong> 是空间和时间的折中。</p><p><strong>我的项目关联</strong> 网关里用 Map 做<strong>本地缓存</strong>和分组：设备号 → 会话状态、场站 → 枪状态、协议类型 → <strong>命令处理器表</strong>。<strong>这条必须强调</strong>：网关是<strong>多线程环境</strong>（Netty Worker 线程 + Kafka 消费线程都在跑），所以生产代码里并发场景一律用 <strong>ConcurrentHashMap</strong>，不用 HashMap。<strong>1.7 头插法并发扩容会成环把 CPU 打满</strong>，属于历史坑，我是查资料时确认的，没在线上的 1.8 环境遇到过。</p><p><strong>面试答题话术</strong> 「HashMap 是<strong>数组加链表加红黑树</strong>。三个点：一是容量取 <strong>2 的幂</strong>，为了用<strong>位运算代替取模</strong>，扩容时只看多出来那一位是 0 还是 1，不用重算 hash；二是<strong>扰动函数</strong>把高位异或进低位，降低<strong>碰撞</strong>；三是 <strong>8 树化、6 退化</strong>，中间留缓冲防止抖动。项目里我的结论是并发场景绝对不用 HashMap——我们的协议网关是多线程的，本地缓存全用 <strong>ConcurrentHashMap</strong>。」</p><hr><h2 id="_5-concurrenthashmap-★★★" tabindex="-1">5. ConcurrentHashMap ★★★ <a class="header-anchor" href="#_5-concurrenthashmap-★★★" aria-label="Permalink to &quot;5. ConcurrentHashMap ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>1.7</strong> 是<strong>分段锁</strong>：整个表切成若干 Segment，每个 Segment 一把锁，锁的是「段」。<strong>1.8</strong> 改成「<strong>桶级锁</strong>」：写只对某个桶的头节点加 synchronized，空桶用 <strong>CAS</strong> 直接写，读完全不加锁；扩容时多个线程能一起帮忙搬。<strong>锁粒度</strong>从段细化到桶，<strong>并发度</strong>自然更高。</p><p><strong>我的项目关联</strong> 网关的<strong>设备会话表</strong>、<strong>协议命令表</strong>（<code>协议类型 + 命令字 → 处理器</code>）都用 <strong>ConcurrentHashMap</strong>，因为会被 Netty 线程和业务线程同时读写。<strong>线上</strong>：命令表在应用启动时由主线程注册、运行时被 IO 线程读，用 ConcurrentHashMap 就是保证<strong>注册过程可见</strong>、<strong>读取安全</strong>，这块没出过问题，但选型上是我明确考虑过的。</p><p><strong>面试答题话术</strong> 「<strong>1.7</strong> 是 Segment <strong>分段锁</strong>，<strong>1.8</strong> 改成<strong>桶级</strong>：写的时候只锁桶的头节点，空桶用 <strong>CAS</strong>，读完全无锁，靠 <strong>volatile</strong> 保证可见性，扩容还能多线程一起搬。所以 1.8 <strong>并发度</strong>比 1.7 高不少。项目里网关的命令表和设备会话表都用它，因为是多线程读写。另外它<strong>不允许 null 的 key 和 value</strong>——因为并发下 get 返回 null 没法区分是「没有」还是「存了个 null」，这个设计原因我会顺便讲。」</p><hr><h2 id="_6-集合框架选型-★★★" tabindex="-1">6. 集合框架选型 ★★★ <a class="header-anchor" href="#_6-集合框架选型-★★★" aria-label="Permalink to &quot;6. 集合框架选型 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 按需求挑：<strong>List</strong> 要<strong>按序可重复</strong>（读多 ArrayList）；<strong>Set</strong> 要<strong>去重</strong>（HashSet 最快，要顺序用 LinkedHashSet，要排序用 TreeSet）；<strong>Map</strong> 要键值（HashMap 最快，要顺序用 LinkedHashMap，要排序用 TreeMap，要并发用 ConcurrentHashMap）。</p><p><strong>我的项目关联</strong> 协议命令表用 Map、设备在线列表用 Set <strong>去重</strong>、批量下发用 List。数据同步、批量写库这种<strong>读多写少</strong>的场景，如果<strong>并发写不多</strong>可以考虑 <strong>CopyOnWriteArrayList</strong>，但项目里我实际都是用普通集合配合<strong>单线程消费</strong>。</p><p><strong>面试答题话术</strong> 「我一般按三条线选：要不要<strong>顺序</strong>、要不要<strong>去重</strong>、要不要<strong>排序</strong>。List 默认 ArrayList，Set 默认 HashSet，Map 默认 HashMap；并发就 <strong>ConcurrentHashMap</strong>。<strong>LinkedHashMap</strong> 还能做 <strong>LRU</strong>——重写 <strong>removeEldestEntry</strong>，开 <strong>accessOrder</strong>，访问过的挪到尾部，超容量删最老的，我们本地缓存有过这个思路但最终用了 Redis。」</p><hr><h2 id="_7-fail-fast-与-fail-safe-★★☆" tabindex="-1">7. fail-fast 与 fail-safe ★★☆ <a class="header-anchor" href="#_7-fail-fast-与-fail-safe-★★☆" aria-label="Permalink to &quot;7. fail-fast 与 fail-safe ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>fail-fast</strong> 是「边遍历边盯着集合变没变」，一变就抛 <strong>ConcurrentModificationException</strong>（ArrayList、HashMap 的迭代器）。<strong>fail-safe</strong> 是「遍历的是<strong>快照</strong>」，改不影响遍历（CopyOnWriteArrayList、ConcurrentHashMap）。</p><p><strong>我的项目关联</strong> 遍历设备列表下发命令时，如果中途有增删就会踩 <strong>fail-fast</strong>。<strong>通用坑</strong>，我们没实际踩到，我写代码时会用 <strong>removeIf</strong> 或者先<strong>拷贝一份</strong>再遍历。</p><p><strong>面试答题话术</strong> 「<strong>fail-fast</strong> 靠 <strong>modCount</strong> 检测，遍历时集合结构变了立刻抛异常；<strong>fail-safe</strong> 遍历的是<strong>副本</strong>，不抛异常但读到的可能是<strong>旧数据</strong>。所以 for-each 里删元素要用 iterator.remove() 或者 removeIf，别直接 list.remove()。」</p><hr><h2 id="_8-泛型擦除-通配符-pecs-★★★" tabindex="-1">8. 泛型擦除 / 通配符 PECS ★★★ <a class="header-anchor" href="#_8-泛型擦除-通配符-pecs-★★★" aria-label="Permalink to &quot;8. 泛型擦除 / 通配符 PECS ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 泛型只在<strong>编译期</strong>存在，编译完类型参数就被<strong>擦除</strong>了——<code>List&lt;String&gt;</code> 和 <code>List&lt;Integer&gt;</code> 运行时是<strong>同一个类</strong>，所以拿不到运行时的<strong>泛型实参</strong>。通配符口诀 <strong>PECS</strong>：<code>? extends T</code> <strong>只能读不能写</strong>（生产数据），<code>? super T</code> <strong>能写</strong>、读出来是 Object（消费数据）。</p><p><strong>我的项目关联</strong> 统一响应体 <code>Result&lt;T&gt;</code>、分页 <code>PageResult&lt;T&gt;</code>、Feign 接口的返回类型全靠泛型。网关里做<strong>协议报文</strong>到<strong>统一模型</strong>的转换时，用过 <code>Converter&lt;S, T&gt;</code> 这种<strong>泛型接口</strong>让每个厂商实现自己的转换。<strong>PECS</strong> 主要用在封装<strong>分页查询</strong>和通用转换工具上。</p><p><strong>面试答题话术</strong> 「泛型是<strong>编译期</strong>概念，编译完<strong>擦除</strong>，<strong>无界擦成 Object</strong>、<strong>有上界擦成上界</strong>，所以运行时拿不到实参，这也是<strong>泛型数组不能 new</strong> 的原因。通配符记 <strong>PECS</strong>：extends 用来读、super 用来写。项目里统一响应体、分页对象、Feign 返回值都用泛型，协议转换那层我用<strong>泛型接口</strong>让每个厂商实现自己的<strong>转换器</strong>，加厂商不用改上层。」</p><hr><h2 id="_9-反射-★★★" tabindex="-1">9. 反射 ★★★ <a class="header-anchor" href="#_9-反射-★★★" aria-label="Permalink to &quot;9. 反射 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 反射就是运行时拿到<strong>类的结构</strong>（构造器、字段、方法、注解）并调用它，<strong>绕开编译期的类型检查</strong>。框架全靠它：<strong>Spring 建 Bean</strong>、<strong>MyBatis 做结果映射</strong>。代价是慢（<strong>动态解析 + 安全检查</strong>）和<strong>破坏封装</strong>。</p><p><strong>我的项目关联</strong><strong>线上真实做法</strong>：<strong>协议插件化</strong>就是反射撑起来的——每个厂商的<strong>命令实现类</strong>上加自定义注解（云快充、新页、科陆各一套），应用启动时按<strong>包扫描</strong>把所有带注解的类扫出来，反射实例化后按「<strong>协议类型 + 命令字</strong>」注册进<strong>命令表</strong>。新增一条指令只要写个带注解的类，不用改主链路。反射对象我们启动时只做一次并<strong>缓存</strong>，不在请求链路上反射。</p><p><strong>面试答题话术</strong> 「反射是运行时获取类信息并调用。项目里我用来做<strong>协议插件化</strong>：启动时<strong>包扫描</strong>带注解的协议类，反射实例化后注册到<strong>命令表</strong>，这样加厂商加指令都不用改<strong>核心代码</strong>。反射慢是因为<strong>动态解析和安全检查</strong>，我们的做法是启动时一次性做完并<strong>缓存</strong>，运行期不反射，所以性能上没有负担。」</p><hr><h2 id="_10-注解与自定义注解-★★★-【简历亮点-高频追问】" tabindex="-1">10. 注解与自定义注解 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_10-注解与自定义注解-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;10. 注解与自定义注解 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong> 注解就是贴在代码上的<strong>标签</strong>，<strong>本身不改逻辑</strong>，得靠别人去读它——运行期用<strong>反射</strong>读，编译期用<strong>注解处理器</strong>读（<strong>Lombok</strong> 就是干这个的）。<code>@Retention</code> 决定它活到哪一步，只有 <strong>RUNTIME</strong> 才能在运行期反射拿到。</p><p><strong>我的项目关联</strong><strong>线上真实做法</strong>：<strong>自定义注解</strong>是我们项目里最常用的招式。协议命令类上的 <code>@YunKuaiChongCmd</code> 这种注解用来做<strong>插件注册</strong>；业务层的 <code>@RepeatSubmit</code> 防重复提交、基于注解的<strong>限流</strong>、<strong>AOP 切面</strong>统一鉴权，都是「<strong>注解 + 切面</strong>」的组合。写自定义注解时 <code>@Retention(RUNTIME)</code> + <code>@Target</code> 是<strong>固定搭配</strong>。</p><p><strong>面试答题话术</strong> 「注解本身只是<strong>元数据</strong>，生效要靠<strong>反射</strong>或者<strong>编译期处理器</strong>，只有 <strong>RUNTIME</strong> 的才能运行期拿到。项目里我大量用<strong>注解驱动</strong>实现：协议命令行加注解做<strong>自动注册</strong>，防重复提交、限流、统一鉴权都是<strong>自定义注解加 AOP 切面</strong>。好处是业务代码只加一行注解，<strong>横切逻辑</strong>集中在切面里，加功能不用改业务代码。」</p><hr><h2 id="_11-bigdecimal-与浮点精度-★★★-【简历亮点-高频追问】" tabindex="-1">11. BigDecimal 与浮点精度 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_11-bigdecimal-与浮点精度-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;11. BigDecimal 与浮点精度 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong><strong>float/double</strong> 是<strong>二进制浮点</strong>，像 0.1 这种十进制小数在二进制里是无限循环的，只能存<strong>近似值</strong>，所以 <code>0.1 + 0.2 != 0.3</code>。金额、电量、费率必须用 <strong>BigDecimal</strong>。三个坑：<strong>构造传字符串</strong>（<code>new BigDecimal(&quot;0.1&quot;)</code>）；<strong>divide 必须给精度或舍入模式</strong>，否则除不尽直接抛异常；比较用 <strong>compareTo</strong> 不用 equals（equals 连精度一起比，<code>1.0</code> 和 <code>1.00</code> 不相等）。</p><p><strong>我的项目关联</strong> 充电订单金额、<strong>分时电价折算</strong>、<strong>资金对账</strong>全程 <strong>BigDecimal</strong>。<strong>通用坑（我们没有实际踩到，但代码规范上一直在防）</strong>：一是 divide 不给 <strong>RoundingMode</strong>，某个地区电价除不尽会抛 <strong>ArithmeticException</strong> 把下单链路打断；二是对账用 equals 比金额，<strong>scale 不同</strong>会误判成对不上。我们的做法是统一封<strong>金额计算工具类</strong>，强制传精度和舍入模式，比较一律 compareTo。<strong>如果面试官追问「你们踩过吗」，就直说规范上防住了，没让它上线</strong>。</p><p><strong>面试答题话术</strong> 「金额场景我全程 <strong>BigDecimal</strong>。原因很直接，double 是<strong>二进制浮点</strong>，0.1 存的就是<strong>近似值</strong>，做对账迟早出问题。三个规范：构造一定传字符串，divide 一定带<strong>舍入模式</strong>，比较一定用 <strong>compareTo</strong>。项目里我们封了<strong>金额工具类</strong>把这些强制住——<strong>费率按秒折算</strong>的场景最容易除不尽，不指定舍入模式就会抛异常。」</p><hr><h2 id="_12-值传递-前端转全栈必考-★★★" tabindex="-1">12. 值传递（前端转全栈必考）★★★ <a class="header-anchor" href="#_12-值传递-前端转全栈必考-★★★" aria-label="Permalink to &quot;12. 值传递（前端转全栈必考）★★★&quot;">​</a></h2><p><strong>通俗理解</strong> Java 只有<strong>值传递</strong>。<strong>基本类型</strong>传的是<strong>值的副本</strong>，改不到外面；<strong>引用类型</strong>传的是「<strong>地址的副本</strong>」，副本和原引用指向<strong>同一个对象</strong>，所以改对象内容外面能看到，但把引用重新指向新对象外面看不到。</p><p><strong>我的项目关联</strong> 这条对我意义挺大——我从 <strong>JS</strong> 转过来，JS 对对象也是<strong>传引用副本</strong>，行为一致，所以上手没障碍。项目里<strong>协议报文</strong>的模型对象在多个 <strong>handler</strong> 之间传递、转换，靠的就是「<strong>改内容生效、换引用不生效</strong>」这个特性来理解数据流。</p><p><strong>面试答题话术</strong> 「Java 只有<strong>值传递</strong>。基本类型传<strong>值副本</strong>，引用类型传<strong>地址副本</strong>。所以方法里<strong>改对象字段</strong>外面能看到，但方法里重新 new 一个、或者把两个引用 <strong>swap</strong>，外面看不到。我从前端转过来，这块和 JS 对 Object 的行为是一致的，所以我理解上没有卡过。」</p><hr><h2 id="_13-异常体系-try-with-resources-★★★" tabindex="-1">13. 异常体系 / try-with-resources ★★★ <a class="header-anchor" href="#_13-异常体系-try-with-resources-★★★" aria-label="Permalink to &quot;13. 异常体系 / try-with-resources ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 根是 <strong>Throwable</strong>，分 <strong>Error</strong>（JVM 级故障，比如 OOM，不捕获）和 <strong>Exception</strong>。Exception 又分<strong>受检</strong>（编译期强制处理，如 IOException）和<strong>非受检</strong>（<strong>RuntimeException</strong>，比如 NPE，靠改代码而不是捕获）。<strong>finally 一定执行</strong>（除非 System.exit），try-with-resources 能自动关资源。</p><p><strong>我的项目关联</strong> 项目里<strong>自定义业务异常</strong>统一继承 <strong>RuntimeException</strong>，避免<strong>全链路污染 throws</strong>；对外接口在 Controller、Kafka 消费者、定时任务这些<strong>边界</strong>统一<strong>兜底捕获</strong>，记日志 + 转成友好响应。网关处理设备报文时，单个报文解析失败只丢这一条、不能让整个连接挂掉，所以每条处理的入口都包了<strong>异常兜底</strong>。</p><p><strong>面试答题话术</strong> 「<strong>受检异常</strong>是调用方能预判能恢复的，强制处理；<strong>非受检</strong>一般是<strong>编程错误</strong>，应该改代码。项目里我的自定义异常都继承 <strong>RuntimeException</strong>，不会有满屏 throws。捕获的位置我放在<strong>系统边界</strong>——Controller、消息消费者、定时任务，每个设备报文的处理入口也单独兜底，保证一条<strong>脏数据</strong>不会把整条连接搞崩，这个在我们网关里是明确的设计。」</p><hr><h2 id="_14-什么时候抛、什么时候捕获-throw-vs-throws-★★☆" tabindex="-1">14. 什么时候抛、什么时候捕获 / throw vs throws ★★☆ <a class="header-anchor" href="#_14-什么时候抛、什么时候捕获-throw-vs-throws-★★☆" aria-label="Permalink to &quot;14. 什么时候抛、什么时候捕获 / throw vs throws ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 自己能处理就<strong>捕获</strong>（<strong>重试</strong>、<strong>降级</strong>、记日志），处理不了或者调用方该知道的就往上抛。<strong>throw</strong> 是「抛出」一个异常对象，<strong>throws</strong> 是「声明」方法可能抛什么，一个动作一个声明。</p><p><strong>我的项目关联</strong> 互联互通对下游的调用失败会<strong>重试 + 降级返回</strong>，属于「能处理」；<strong>参数校验失败</strong>、设备不存在这种直接抛<strong>业务异常</strong>让上层统一转响应。原则是<strong>不吞异常</strong>、也不拿异常当<strong>流程控制</strong>。</p><p><strong>面试答题话术</strong> 「我的原则是<strong>能恢复就捕获</strong>，恢复不了或者调用方该知道就抛。<strong>throw 是抛对象，throws 是声明</strong>，别混。另外不在 catch 里无脑 <code>catch (Exception)</code> 然后返回 null，至少<strong>打日志</strong>，这是我在 review 里的<strong>硬要求</strong>。」</p><hr><h2 id="_15-final-finally-finalize-已废弃-★★☆" tabindex="-1">15. final / finally（finalize 已废弃）★★☆ <a class="header-anchor" href="#_15-final-finally-finalize-已废弃-★★☆" aria-label="Permalink to &quot;15. final / finally（finalize 已废弃）★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>final</strong> 修类不能继承、修方法不能重写、修变量引用不能改。<strong>finally</strong> 是异常处理里一定会执行的那段。<strong>finalize</strong> 是对象回收前调用的方法，<strong>JDK9 起废弃</strong>了——<strong>执行时机不确定</strong>还能把对象「复活」，别用。</p><p><strong>我的项目关联</strong> 工具类、常量类用 <strong>final</strong> 修饰防止被继承破坏；协议命令的<strong>处理器基类</strong>被各厂商子类继承，但基类里的<strong>编解码入口方法</strong>是 final 的，保证<strong>流程不被改坏</strong>。finalize 项目里从没用过。</p><p><strong>面试答题话术</strong> 「<strong>final 和 finally 没有关系</strong>，只是拼写像。<strong>finalize</strong> 已经废弃了，因为<strong>执行时机不确定</strong>、可能<strong>延迟 GC</strong>、还能<strong>复活对象</strong>，要释放资源应该用 try-with-resources 或者 <strong>Cleaner</strong>。项目里我在<strong>命令处理器基类</strong>上把编解码主流程设成 final，只开放子类实现业务方法，保证流程一致。」</p><hr><h2 id="_16-类初始化顺序-★★☆" tabindex="-1">16. 类初始化顺序 ★★☆ <a class="header-anchor" href="#_16-类初始化顺序-★★☆" aria-label="Permalink to &quot;16. 类初始化顺序 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong> 顺序是：<strong>父类静态 → 子类静态 → 父类实例变量/代码块 → 父类构造器 → 子类实例变量/代码块 → 子类构造器</strong>。静态部分只在类<strong>第一次主动使用</strong>时<strong>执行一次</strong>。</p><p><strong>我的项目关联</strong><strong>协议处理器基类</strong>的静态块里注册<strong>通用配置</strong>，实例块做每个处理器自己的初始化，所以顺序必须是「<strong>静态先于实例</strong>」。这个是写代码时自然遵守的，没踩过坑。</p><p><strong>面试答题话术</strong> 「口诀是<strong>先静态后实例、先父后子</strong>，静态只执行一次。<strong>new 子类会先初始化父类</strong>。这个我一般在写<strong>继承体系</strong>的时候会注意，比如基类的<strong>静态注册</strong>一定要先于子类实例的构建。」</p><hr><h2 id="_17-不可变类-★★★" tabindex="-1">17. 不可变类 ★★★ <a class="header-anchor" href="#_17-不可变类-★★★" aria-label="Permalink to &quot;17. 不可变类 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 四步：类 <strong>final</strong>、字段 <strong>private final</strong>、不给 <strong>setter</strong>、可变字段（数组/集合/Date）在构造和 getter 上做<strong>防御性拷贝</strong>。<strong>String</strong>、<strong>Integer</strong>、<strong>BigDecimal</strong>、<strong>LocalDate</strong> 都是这么做的。</p><p><strong>我的项目关联</strong> 协议里解析出来的<strong>报文对象</strong>、<strong>费率配置对象</strong>，我们尽量做成<strong>不可变</strong>的，避免在多个 handler 之间被意外改掉。费率、金额这种<strong>配置类</strong>尤其，一旦可变很容易出现「某个地方算错了费率」这种<strong>难查</strong>的问题。</p><p><strong>面试答题话术</strong> 「<strong>不可变类</strong>就是 <strong>final 类 + private final 字段 + 不提供 setter</strong>，如果字段是集合或日期还要<strong>防御性拷贝</strong>。好处是<strong>线程安全</strong>、可以被<strong>安全共享</strong>。项目里费率、金额这种配置对象我倾向做成不可变的，避免在多个处理环节被误改。String 就是标准实现，它不可变所以能进<strong>常量池</strong>、能当 key。」</p><hr><h2 id="_18-字节码-jdk-jre-jvm-★★★" tabindex="-1">18. 字节码 / JDK-JRE-JVM ★★★ <a class="header-anchor" href="#_18-字节码-jdk-jre-jvm-★★★" aria-label="Permalink to &quot;18. 字节码 / JDK-JRE-JVM ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 源码用 <strong>javac</strong> 编译成<strong>字节码</strong>（.class），<strong>JVM</strong> 负责执行；字节码跟<strong>平台无关</strong>，所以「<strong>一次编译到处运行</strong>」。<strong>JDK ⊃ JRE ⊃ JVM</strong>——JVM 负责跑，JRE 是 JVM + <strong>核心类库</strong>，JDK 再多了<strong>编译器</strong>这些开发工具。</p><p><strong>我的项目关联</strong> 网关用 <strong>JDK21</strong> 跑，基础镜像是 jre，构建阶段才用 jdk，靠<strong>多阶段构建</strong>把<strong>镜像做小</strong>。字节码层面我们没直接操作过，但 <strong>AOP 代理</strong>、协议插件的<strong>动态注册</strong>都发生在这一层之下。</p><p><strong>面试答题话术</strong> 「字节码是 JVM 的<strong>中间指令</strong>，跟平台无关，各平台 JVM 负责翻译执行，所以能<strong>跨平台</strong>；<strong>JIT</strong> 还能把<strong>热点字节码</strong>编译成<strong>本地机器码</strong>提速。<strong>JDK 包含 JRE 包含 JVM</strong>。项目里 Docker 构建阶段用 jdk，运行镜像用 jre，就是为了<strong>减小体积</strong>。」</p><hr><h2 id="_19-hash-冲突的解决办法-★★★" tabindex="-1">19. hash 冲突的解决办法 ★★★ <a class="header-anchor" href="#_19-hash-冲突的解决办法-★★★" aria-label="Permalink to &quot;19. hash 冲突的解决办法 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong> 常见四种：<strong>链地址法</strong>（冲突的挂成链表，<strong>HashMap</strong> 用这个）、<strong>开放定址法</strong>（往后探测空位，<strong>ThreadLocalMap</strong> 用<strong>线性探测</strong>）、<strong>再哈希</strong>、<strong>公共溢出区</strong>。HashMap 选链地址是因为<strong>实现简单</strong>、删除方便，链长了还能转<strong>红黑树</strong>。</p><p><strong>我的项目关联</strong> 知道结论就够了——我们不需要自己实现哈希表。实际相关的是<strong>设备分片</strong>：<strong>Kafka</strong> 按设备号<strong>哈希分区</strong>时，用的是 <strong>murmur3_128</strong> 而不是简单取模，就是为了让分片更<strong>均匀</strong>，避免某几个分区成<strong>热点</strong>。</p><p><strong>面试答题话术</strong> 「主要是<strong>链地址法</strong>和<strong>开放定址法</strong>，HashMap 用链地址，链表长了转红黑树把最坏情况从 O(n) 降到 O(logn)；<strong>ThreadLocalMap</strong> 用的是<strong>线性探测</strong>。项目里我真正用到哈希思想的地方是<strong>数据分片</strong>——Kafka 按设备号哈希，用 <strong>murmur3</strong> 保证分布均匀，防止<strong>热点分区</strong>。」</p><hr><h2 id="_20-bio-nio-aio-★★★-【简历亮点-高频追问】" tabindex="-1">20. BIO / NIO / AIO ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_20-bio-nio-aio-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;20. BIO / NIO / AIO ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong><strong>BIO</strong> 是<strong>一连接一线程</strong>，读写都阻塞，扛不住高并发。<strong>NIO</strong> 是<strong>同步非阻塞 + 多路复用</strong>，一个线程用 <strong>Selector</strong> 管一堆连接，谁有事件处理谁。<strong>AIO</strong> 是异步，读写完成<strong>回调通知</strong>你。NIO 三大件：Buffer（缓冲区）、Channel（双向通道）、Selector（多路复用器），底层靠 Linux 的 <strong>epoll</strong>。</p><p><strong>我的项目关联</strong><strong>线上</strong>：我们的<strong>充电桩协议网关</strong>就是基于 <strong>Netty</strong>（NIO 封装）做的 <strong>TCP 长连接</strong>服务，向上对接业务、向下接各厂商充电桩。为什么不用 BIO：设备量上去以后一连接一线程扛不住；为什么不用 AIO：Linux 上实现不成熟，还是 epoll 模拟，<strong>跨平台一致性</strong>不如 NIO。Netty 的 <strong>ChannelHandler 链路</strong>正好把<strong>编解码</strong>、心跳、鉴权拆成独立 handler。</p><p><strong>面试答题话术</strong> 「<strong>BIO</strong> 一连接一线程，扛不住高并发；<strong>NIO</strong> 是<strong>多路复用</strong>，一个 Selector 管很多连接，底层是 <strong>epoll</strong>；<strong>AIO</strong> 是异步回调，但 Linux 上不成熟。我们的协议网关选 <strong>Netty</strong>，本质是 NIO，理由是<strong>设备长连接</strong>场景需要多路复用，而且 Netty 的 <strong>handler 链路</strong>能把编解码、心跳、鉴权拆开。AIO 我没用过，主要是不成熟。」</p><hr><h2 id="_21-虚拟线程-vs-平台线程-★★★-【简历亮点-高频追问】" tabindex="-1">21. 虚拟线程 vs 平台线程 ★★★ 【简历亮点，高频追问】 <a class="header-anchor" href="#_21-虚拟线程-vs-平台线程-★★★-【简历亮点-高频追问】" aria-label="Permalink to &quot;21. 虚拟线程 vs 平台线程 ★★★ 【简历亮点，高频追问】&quot;">​</a></h2><p><strong>通俗理解</strong><strong>平台线程</strong> <strong>1:1</strong> 绑操作系统线程，贵，几千个就到头；<strong>虚拟线程</strong>是 JVM 调度的 <strong>M:N</strong>，挂在少量<strong>载体线程</strong>上，<strong>IO 阻塞时会自动卸载</strong>，载体线程立刻去跑别的任务。所以只适合 <strong>IO 密集型</strong>，<strong>CPU 密集型</strong>用没收益还多一层调度。</p><p><strong>我的项目关联</strong><strong>线上</strong>：我们的网关和互联互通服务是典型 <strong>IO 密集型</strong>——等数据库、等下游 HTTP、等 Redis，<strong>Java 21</strong> 升级后把这类业务换成 <code>Executors.newVirtualThreadPerTaskExecutor()</code>。踩到两个点：一是<strong>数据库连接池上限没变</strong>，线程多了但池子还是那么大，所以关键是别让<strong>连接被长时间占着</strong>；二是老代码里有 <code>synchronized</code> 包着 IO 的会 <strong>pin 住载体线程</strong>，这类改成了 <strong>ReentrantLock</strong>。</p><p><strong>面试答题话术</strong> 「<strong>虚拟线程</strong>我在网关和互联互通服务里实际用过，这两个服务都是 <strong>IO 密集型</strong>的，收益比较明显。原理上平台线程 <strong>1:1</strong> 映射 OS 线程，虚拟线程是 JVM 调度的 M:N，<strong>阻塞时自动卸载</strong>让载体线程去干别的。落地踩了两个点：<strong>连接池并发上限不会跟着变</strong>，真正要控的是连接占用时长；还有 synchronized 包 IO 会 <strong>pin 住载体线程</strong>，我们换成 <strong>ReentrantLock</strong> 就好了。<strong>CPU 密集型</strong>的任务我没用，没收益。」</p><hr><h2 id="_22-函数式接口-lambda-stream-★★★" tabindex="-1">22. 函数式接口 / Lambda / Stream ★★★ <a class="header-anchor" href="#_22-函数式接口-lambda-stream-★★★" aria-label="Permalink to &quot;22. 函数式接口 / Lambda / Stream ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>函数式接口</strong>就是<strong>只有一个抽象方法</strong>的接口。<strong>Lambda</strong> 是它的简写实现。<strong>Stream</strong> 是「<strong>数据源 → 中间操作（惰性，不立刻执行）→ 终结操作（触发执行）</strong>」的流水线，中间操作要等终结操作才跑。</p><p><strong>我的项目关联</strong> 项目里用得最多的是 <strong>Stream</strong>：<strong>List 转 Map</strong>（设备列表转 <code>Map&lt;设备号, 设备&gt;</code>）、按条件过滤订单、<strong>分组统计</strong>（按场站/按日期分组算金额）、集合转换。<code>parallelStream</code> 我用得很克制——它用的是共享的 <strong>ForkJoinPool</strong>，如果里面还做<strong>阻塞 IO</strong> 会<strong>拖垮整个池子</strong>，我们这种 IO 场景基本不用并行流。</p><p><strong>面试答题话术</strong> 「<strong>Stream</strong> 是<strong>惰性</strong>的，没有终结操作中间操作不执行；map 是<strong>一对一</strong>，flatMap 是<strong>一对多拍平</strong>。项目里我主要用 Stream 做<strong>集合转换</strong>和分组统计，比如设备列表转 Map、订单按场站分组。<strong>parallelStream</strong> 我基本不用——它共享 <strong>ForkJoinPool</strong>，里面一旦有阻塞操作会把整个池子拖垮，我们的场景都是 <strong>IO 密集型</strong>，不适合。」</p><hr><h2 id="_23-optional-java-8-新特性-★★★" tabindex="-1">23. Optional / Java 8 新特性 ★★★ <a class="header-anchor" href="#_23-optional-java-8-新特性-★★★" aria-label="Permalink to &quot;23. Optional / Java 8 新特性 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>Optional</strong> 是包装「<strong>可能为空的值</strong>」的容器，让「<strong>可能没值</strong>」这件事在<strong>方法签名</strong>上就看得见。<code>orElse</code> 无论有没有值都会算参数，<code>orElseGet</code> 才是<strong>惰性</strong>的。用法上它只适合当<strong>方法返回值</strong>，不当字段、不当参数。</p><p><strong>我的项目关联</strong> 项目里查询接口返回单个对象时用 <strong>Optional</strong> 表达「<strong>可能查不到</strong>」，比如按设备号查在线设备。但更多场景我直接用<strong>返回 null + 业务判断</strong>，因为 Optional 用在字段和参数上反而<strong>增加复杂度</strong>。Java 8 的 <strong>Stream</strong>、<strong>新时间 API</strong>、<strong>CompletableFuture</strong> 是项目里天天在用的。</p><p><strong>面试答题话术</strong> 「<strong>Optional</strong> 主要是把「<strong>可能为空</strong>」<strong>显式化</strong>，用法上只建议当<strong>返回值</strong>。坑是 <code>orElse</code> 不管有没有值都会执行参数，所以<strong>有开销的兜底</strong>要用 <code>orElseGet</code>。项目里查单个对象我用它，但字段和参数不用，那样反而更啰嗦。」</p><hr><h2 id="_24-jdk-版本演进-8-11-17-21-★★☆" tabindex="-1">24. JDK 版本演进 8/11/17/21 ★★☆ <a class="header-anchor" href="#_24-jdk-版本演进-8-11-17-21-★★☆" aria-label="Permalink to &quot;24. JDK 版本演进 8/11/17/21 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>8</strong> 是<strong>分水岭</strong>（Lambda、Stream、Optional、新时间 API）；<strong>11</strong> 加了 var、新 HTTP Client；<strong>17</strong> 加了 record、sealed、文本块、<strong>instanceof 模式匹配</strong>；<strong>21</strong> 的杀手锏是<strong>虚拟线程</strong>。</p><p><strong>我的项目关联</strong> 我们新服务直接上 <strong>Java 21 + Spring Boot 3.x</strong>，所以 17 的<strong>记录类</strong>、<strong>文本块</strong>、<strong>switch 表达式</strong>都在用，21 的<strong>虚拟线程</strong>用在 IO 密集服务。等于跳过了 8 到 17 的<strong>历史包袱</strong>，这点我面试时会当成<strong>优势</strong>讲——不用背<strong>兼容性负担</strong>。</p><p><strong>面试答题话术</strong> 「我们新服务是 <strong>Java 21 + Spring Boot 3.4</strong>，所以直接吃到了 <strong>record</strong>、<strong>文本块</strong>、<strong>模式匹配</strong>这些红利，<strong>虚拟线程</strong>也实打实用在 IO 密集服务上。8 的 Lambda、Stream、Optional 是基础，<strong>新时间 API</strong> 我要求自己全用 <strong>LocalDateTime</strong>，不用老的 Date。」</p><hr><h2 id="_25-comparable-与-comparator-★★☆" tabindex="-1">25. Comparable 与 Comparator ★★☆ <a class="header-anchor" href="#_25-comparable-与-comparator-★★☆" aria-label="Permalink to &quot;25. Comparable 与 Comparator ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>Comparable</strong> 是「<strong>我自己知道自己怎么排序</strong>」——类实现 <strong>compareTo</strong>，只有一种<strong>自然顺序</strong>。<strong>Comparator</strong> 是「<strong>外人给我定排序规则</strong>」——不改原类，能定义多种，配合 lambda 很方便。</p><p><strong>我的项目关联</strong> 订单列表按<strong>时间倒序</strong>、设备按<strong>上线时间排序</strong>，我用 <code>Comparator.comparing(...).thenComparing(...)</code> 在<strong>调用处</strong>拼，不往实体类里塞<strong>排序逻辑</strong>。需要<strong>多字段排序</strong>（先按场站再按时间）的时候 Comparator 明显更方便。</p><p><strong>面试答题话术</strong> 「<strong>Comparable</strong> 是类自己实现的<strong>自然排序</strong>，只能一种；<strong>Comparator</strong> 是<strong>外部规则</strong>，能多种，也不<strong>侵入原类</strong>。我一般用 Comparator，<strong>链式</strong>写多字段排序很清爽，比如先按场站再按时间。」</p><hr><h2 id="_26-枚举-★★☆" tabindex="-1">26. 枚举 ★★☆ <a class="header-anchor" href="#_26-枚举-★★☆" aria-label="Permalink to &quot;26. 枚举 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>枚举</strong>本质是继承 <strong>Enum</strong> 的 <strong>final 类</strong>，每个常量都是<strong>唯一实例</strong>，构造器私有。它天然<strong>防反射、防反序列化破坏</strong>，所以是实现<strong>单例</strong>最稳的方式。</p><p><strong>我的项目关联</strong> 项目里大量用<strong>枚举</strong>表达固定集合：<strong>订单状态</strong>、设备状态、<strong>协议类型</strong>、<strong>支付渠道</strong>、<strong>故障码</strong>。特别是<strong>订单状态机</strong>，<strong>状态流转</strong>判断全靠枚举。枚举里挂字段（比如状态码 + 中文描述）是我们的常规写法。</p><p><strong>面试答题话术</strong> 「<strong>枚举</strong>是 <strong>final 类</strong>，<strong>实例唯一</strong>，天然<strong>防反射和反序列化</strong>，所以是<strong>单例的最佳实践</strong>。项目里订单状态、设备状态、协议类型、支付渠道都是枚举，枚举里带 <strong>code 和描述字段</strong>是我们的标准写法。<strong>状态机</strong>判断流转合法性也基于枚举。」</p><hr><h2 id="_27-object-常用方法-★★☆" tabindex="-1">27. Object 常用方法 ★★☆ <a class="header-anchor" href="#_27-object-常用方法-★★☆" aria-label="Permalink to &quot;27. Object 常用方法 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>equals、hashCode、toString、clone、getClass</strong>，加上<strong>线程协作</strong>的 <strong>wait/notify/notifyAll</strong>。<strong>finalize 已经废弃</strong>，忽略。</p><p><strong>我的项目关联</strong><strong>DTO 和实体类</strong>都会重写 <strong>toString</strong> 方便<strong>打日志</strong>——网关排查设备报文问题时主要靠日志，toString 写清楚省事。<strong>wait/notify</strong> 项目里基本不用，线程协作我们走<strong>并发包的工具类</strong>。</p><p><strong>面试答题话术</strong> 「常用的是 <strong>equals、hashCode、toString、clone、getClass</strong>，还有 <strong>wait/notify</strong> 这三个。<strong>finalize 废弃了</strong>不用提。项目里我特别重视 <strong>toString</strong>，因为<strong>设备报文排查</strong>基本靠日志，对象打出来能看懂很关键。」</p><hr><h2 id="_28-深拷贝浅拷贝-serialversionuid-★★☆" tabindex="-1">28. 深拷贝浅拷贝 / serialVersionUID ★★☆ <a class="header-anchor" href="#_28-深拷贝浅拷贝-serialversionuid-★★☆" aria-label="Permalink to &quot;28. 深拷贝浅拷贝 / serialVersionUID ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>浅拷贝</strong>只复制对象本身，里面的<strong>引用字段</strong>还指向<strong>同一个对象</strong>；<strong>深拷贝</strong>是把<strong>引用链</strong>上的对象全复制一份。<code>clone()</code> 默认是浅拷贝。<strong>serialVersionUID</strong> 是<strong>序列化版本号</strong>，不显式声明的话类一改旧数据就<strong>反序列化失败</strong>。</p><p><strong>我的项目关联</strong> 跨服务传对象走<strong>序列化</strong>（网关 → 业务服务、网关 → 下游运营商），DTO 我们统一显式声明 <strong>serialVersionUID</strong>，避免加个字段就<strong>反序列化不兼容</strong>。深拷贝项目里用得少，有个<strong>配置快照</strong>场景直接用的<strong>序列化拷贝</strong>，没自己写 clone。</p><p><strong>面试答题话术</strong> 「<strong>浅拷贝是引用共享，深拷贝是引用链全复制</strong>。项目里我更多是保证 DTO 显式声明 <strong>serialVersionUID</strong>，防止类改动导致<strong>反序列化不兼容</strong>。深拷贝我们用序列化方式做过<strong>配置快照</strong>。知道结论、能用对就行，不用背 clone 的实现细节。」</p><hr><h2 id="_29-四种内部类-★☆☆" tabindex="-1">29. 四种内部类 ★☆☆ <a class="header-anchor" href="#_29-四种内部类-★☆☆" aria-label="Permalink to &quot;29. 四种内部类 ★☆☆&quot;">​</a></h2><p>一句话：<strong>成员 / 静态 / 局部 / 匿名</strong>四种。业务里只用<strong>静态内部类</strong>（Builder、静态工具）和<strong>匿名内部类</strong>（现在基本被 Lambda 替代）。唯一要记的结论——<strong>静态内部类不持有外部引用，不会内存泄漏</strong>。不用复习。</p><hr><h2 id="_30-重载与重写-★☆☆" tabindex="-1">30. 重载与重写 ★☆☆ <a class="header-anchor" href="#_30-重载与重写-★☆☆" aria-label="Permalink to &quot;30. 重载与重写 ★☆☆&quot;">​</a></h2><p>一句话：<strong>重载</strong>看<strong>参数列表</strong>、<strong>编译期决定</strong>、同一个类里；<strong>重写</strong>看<strong>方法签名一致</strong>、<strong>运行期决定</strong>、父子类之间。只返回值不同<strong>不算重载</strong>，<strong>静态方法不能被重写只会被隐藏</strong>。低频，扫一眼即可。</p><hr><h2 id="_31-抽象类和接口的异同-java-8-之后接口默认方法-静态方法的变化-★★★" tabindex="-1">31. 抽象类和接口的异同（Java 8 之后接口默认方法/静态方法的变化）★★★ <a class="header-anchor" href="#_31-抽象类和接口的异同-java-8-之后接口默认方法-静态方法的变化-★★★" aria-label="Permalink to &quot;31. 抽象类和接口的异同（Java 8 之后接口默认方法/静态方法的变化）★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>抽象类</strong>是「是一种」关系，是类的模板——能写成员变量、构造器、普通方法，<strong>单继承</strong>；<strong>接口</strong>是「能做」关系，是行为的契约——字段默认 public static final，方法默认抽象，<strong>多实现</strong>。一句话：抽象类管「是什么、有什么状态」，接口管「能做什么」。<strong>Java 8</strong> 之后接口能写 <strong>default 方法</strong>（带默认实现，实现类可覆盖可不覆盖）和 <strong>static 方法</strong>（只能接口名调用），这是为了「<strong>接口演进</strong>」——给老接口加新方法不用所有实现类都改。</p><p><strong>我的项目关联</strong> 网关的「<strong>编解码处理器</strong>」体系就是抽象类 + 接口的组合：<strong>抽象基类</strong>放通用字段（配置、编解码上下文）和公共流程，接口定义「编解码、心跳、鉴权」这些能力，各厂商实现类<strong>继承基类、实现接口</strong>。Java 8 的 <strong>default 方法</strong>我用在<strong>接口演进</strong>上——给一个已经有很多实现类的接口加新方法时，用 default 提供默认实现，老实现类不用动，避免一改接口<strong>全部编译报错</strong>；<strong>static 方法</strong>用来放接口的<strong>工厂方法</strong>，比如 <code>ProtocolConverter.create(type)</code> 返回对应厂商转换器。</p><p><strong>面试答题话术</strong> 「先说结论：<strong>抽象类代表 is-a</strong>，管状态和模板；<strong>接口代表 can-do</strong>，管<strong>行为契约</strong>，可以多实现。抽象类能有构造器、成员变量、普通方法，接口字段默认 public static final。<strong>Java 8</strong> 之后接口多了 <strong>default 和 static</strong>——default 是为了<strong>接口演进</strong>，加新方法不用所有实现类都改；static 是放接口的<strong>工厂或工具方法</strong>，只能接口名调。项目里我做协议处理器就是<strong>抽象基类</strong>放公共流程、接口定义编解码能力，default 方法我用来给老接口加方法，避免所有实现类都得改一遍。」</p><hr><h2 id="_32-使用-java-8-的优点-★★★" tabindex="-1">32. 使用 Java 8 的优点 ★★★ <a class="header-anchor" href="#_32-使用-java-8-的优点-★★★" aria-label="Permalink to &quot;32. 使用 Java 8 的优点 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>Java 8</strong> 是 Java 最大的<strong>分水岭</strong>，三个核心：<strong>Lambda</strong> 让代码从「怎么做」变成「做什么」，把匿名内部类一行搞定；<strong>Stream</strong> 让集合操作变成<strong>声明式、可链式、能并行</strong>；<strong>新时间 API</strong>（LocalDate/LocalDateTime）把老 Date 的线程安全和 API 混乱问题解决掉。配套还有接口 <strong>default/static 方法</strong>、<strong>Optional</strong>、<strong>CompletableFuture</strong>、方法引用。</p><p><strong>我的项目关联</strong> 我们新服务跑在 <strong>Java 21</strong> 上，Java 8 这些特性是<strong>地基</strong>、天天在用：<strong>Stream</strong> 做设备列表转 Map、订单按场站分组统计、按条件过滤；<strong>Lambda</strong> 让 handler 注册、命令映射这些代码从一堆匿名类变成一行；<strong>LocalDateTime</strong> 处理充电订单的时间字段，<strong>分时电价按小时切分</strong>就靠它；<strong>CompletableFuture</strong> 做互联互通里对多个下游的<strong>并发调用合并结果</strong>。没有 Java 8 的这套东西，项目里这些列表处理和异步调用代码量会翻倍。</p><p><strong>面试答题话术</strong> 「<strong>Java 8</strong> 我理解是三个核心价值：<strong>Lambda 让代码简洁</strong>，匿名内部类一行搞定；<strong>Stream</strong> 把集合操作从命令式改成<strong>声明式</strong>，filter、map、groupingBy 链式写，可读性和正确性都更高；<strong>新时间 API 线程安全、不可变、API 清晰</strong>，替代了又乱又线程不安全的 Date。项目里我用 Stream 做设备列表和订单的过滤分组，用 <strong>LocalDateTime</strong> 处理<strong>分时电价按小时切分</strong>，用 <strong>CompletableFuture</strong> 做下游并发调用，这些都是 Java 8 打的基础。面试官要问『优点』，我就围绕『简洁、声明式、时间 API 更安全』这三点展开。」</p><hr><h2 id="_33-集合与流-stream-有何不同-★★★" tabindex="-1">33. 集合与流（Stream）有何不同 ★★★ <a class="header-anchor" href="#_33-集合与流-stream-有何不同-★★★" aria-label="Permalink to &quot;33. 集合与流（Stream）有何不同 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>集合</strong>是「<strong>数据的存储</strong>」，是内存里的容器，元素都在、能反复遍历、有增删改查；<strong>Stream</strong> 是「<strong>对数据的计算管道</strong>」，<strong>不存数据</strong>，只描述「从哪来、怎么处理、输出什么」，<strong>惰性</strong>的，<strong>一次消费完就没了</strong>。核心区别：集合重存储、Stream 重计算；集合可复用、Stream 不可复用；集合是<strong>急切</strong>的（add 就存进去），Stream 中间操作是惰性的，要<strong>终结操作</strong>才触发。</p><p><strong>我的项目关联</strong> 项目里很典型：从数据库或 Kafka 拿到的<strong>充电订单列表</strong>是「<strong>集合</strong>」，存着要处理的数据；要统计、过滤、转换时才把集合 <code>.stream()</code> 变成流来做计算——订单列表转 <code>Map&lt;订单号, 订单&gt;</code>、按场站<strong>分组合计金额</strong>、过滤掉测试订单，都是「<strong>集合做存储、Stream 做计算</strong>」的配合。<strong>通用坑</strong>：一个 <strong>Stream 只能消费一次</strong>，把它当集合反复遍历会抛 <code>IllegalStateException: stream has already been operated upon or closed</code>，我们写代码时会用变量先存好结果，不重复消费同一个流。</p><p><strong>面试答题话术</strong> 「<strong>集合和 Stream 是两码事</strong>：集合是<strong>数据的容器</strong>，存东西、能反复遍历、有增删改；<strong>Stream 是计算管道</strong>，不存数据，它描述数据怎么处理，<strong>惰性</strong>的，<strong>终结操作触发执行</strong>，而且<strong>消费一次就没了</strong>。可以这么理解——<strong>集合是仓库，Stream 是流水线</strong>。项目里我从数据库或 Kafka 拿到的订单列表就是集合，要过滤、分组、统计的时候再转成 Stream。有个点要注意：<strong>Stream 不能复用</strong>，把它当集合反复遍历会报 stream has already been operated upon or closed，所以我一般转一次流、算一次结果就结束。」</p><hr><h2 id="_34-predicate-和-consumer-等常用函数式接口的区别与用法-★★★" tabindex="-1">34. Predicate 和 Consumer 等常用函数式接口的区别与用法 ★★★ <a class="header-anchor" href="#_34-predicate-和-consumer-等常用函数式接口的区别与用法-★★★" aria-label="Permalink to &quot;34. Predicate 和 Consumer 等常用函数式接口的区别与用法 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>Java 8</strong> 在 <code>java.util.function</code> 里给了一组<strong>标准函数式接口</strong>：<strong>Predicate</strong> 接收一个参数返回 boolean，用来「判断」；<strong>Consumer</strong> 接收一个参数没返回值，用来「消费/执行操作」；<strong>Function&lt;T,R&gt;</strong> 接收 T 返回 R，用来「转换」；<strong>Supplier</strong> 无参返回一个值，用来「供应」；<strong>BiFunction、BiConsumer</strong> 是两个参数版本。有了它们就不用自己造接口，直接配 <strong>Lambda</strong>。</p><p><strong>我的项目关联</strong> 项目里 <strong>Stream</strong> 的操作背后就是这些接口：<code>filter</code> 传 <strong>Predicate</strong>（过滤测试订单、过滤下线设备），<code>map</code> 传 <strong>Function</strong>（实体转 DTO、设备列表转 Map 时提取 key/value），<code>forEach</code> 传 <strong>Consumer</strong>（批量下发命令、打日志），<code>Optional.orElseGet</code> 传 <strong>Supplier</strong>（<strong>惰性兜底</strong>）。遇到<strong>判断条件要复用</strong>的场景，我会把 Predicate 提成<strong>变量或方法</strong>，比如「是不是测试订单」这个条件在多处复用，写成 <code>Predicate&lt;Order&gt; isTestOrder = o -&gt; TEST.equals(o.getSource());</code> 就清晰很多。</p><p><strong>面试答题话术</strong> 「这四个我按『做什么』来记：<strong>Predicate 判断、返回 boolean</strong>；<strong>Consumer 消费、只执行不返回</strong>；<strong>Function 转换、输入 T 输出 R</strong>；<strong>Supplier 供应、无参返回值</strong>。它们和 <strong>Stream 是配套的</strong>——filter 用 Predicate，map 用 Function，forEach 用 Consumer，orElseGet 用 Supplier。项目里过滤测试订单、实体转 DTO、批量下发、<strong>惰性兜底</strong>，都是直接配 <strong>Lambda</strong> 用这些接口。我还会把复用的判断条件提成 <strong>Predicate 变量</strong>，比在 filter 里重复写一长串 lambda <strong>可读性</strong>好。」</p><hr><h2 id="_35-stream-的-peek-方法作用与副作用-★★☆" tabindex="-1">35. Stream 的 peek() 方法作用与副作用 ★★☆ <a class="header-anchor" href="#_35-stream-的-peek-方法作用与副作用-★★☆" aria-label="Permalink to &quot;35. Stream 的 peek() 方法作用与副作用 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>peek</strong> 是<strong>中间操作</strong>，对流里每个元素执行一个 <strong>Consumer</strong>，主要用于<strong>调试</strong>——在流水线中间「偷看」一下当前元素长什么样，<strong>不改变元素、不改变流</strong>。它也是<strong>惰性</strong>的，没有终结操作就不执行；而且官方明确说它的<strong>行为不保证</strong>——遇到 count、findFirst 这种会<strong>短路</strong>或不需要所有元素的终结操作，peek 可能根本不被调用。</p><p><strong>我的项目关联</strong> 我主要用它打印<strong>中间状态</strong>做排查：比如设备列表过滤之后、分组之前 peek 一下，看看过滤结果对不对。<strong>通用坑</strong>：别拿 peek 做<strong>业务逻辑</strong>（在里面写库、发消息），因为它不是为<strong>副作用</strong>设计的，遇到<strong>短路操作</strong>或<strong>并行流</strong>时<strong>执行次数不保证</strong>，容易「莫名其妙少执行」。真要做副作用应该用 <strong>forEach 终结操作</strong>，或者干脆写显式循环。我们项目里 peek 只出现在调试代码里，正式逻辑从不用它。</p><p><strong>面试答题话术</strong> 「<strong>peek 是中间操作</strong>，作用是<strong>调试时偷看元素</strong>，接收一个 <strong>Consumer</strong>，<strong>不改变元素也不改变流</strong>。两个点要注意：它是<strong>惰性</strong>的，没有终结操作不执行；而且它的<strong>执行不保证</strong>——遇到 count、findFirst 这类会<strong>短路</strong>或不需要所有元素的终结操作，peek 可能压根不被调用。所以我的原则是 peek 只用来打印调试，绝不往里写<strong>业务副作用</strong>，正式逻辑用 forEach 或显式循环。」</p><hr><h2 id="_36-接口中的静态方法有什么作用-★★☆" tabindex="-1">36. 接口中的静态方法有什么作用 ★★☆ <a class="header-anchor" href="#_36-接口中的静态方法有什么作用-★★☆" aria-label="Permalink to &quot;36. 接口中的静态方法有什么作用 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>Java 8</strong> 允许接口里写 <strong>static 方法</strong>，和类的 static 方法一样，<strong>属于接口本身</strong>，只能通过「<strong>接口名.方法名</strong>」调用，实现类<strong>不能继承也不能覆盖</strong>。作用就一个：放「和这个接口强相关、但不需要实例状态」的<strong>工具方法或工厂方法</strong>，避免单独再建一个工具类。</p><p><strong>我的项目关联</strong> 项目里协议转换接口就用了<strong>静态工厂方法</strong>，比如 <code>ProtocolConverter.create(type)</code> 返回对应厂商的<strong>转换器</strong>，调用方不用关心实现类是谁；还有把<strong>常量校验逻辑</strong>（设备号格式校验）也放成接口静态方法，紧贴接口语义。好处是「<strong>接口 + 它的工厂</strong>」放一起，不用像以前那样接口一个文件、工厂或工具类另一个文件。要注意的是实现类里不能用实例方式或 <code>super.</code> 调这个静态方法，只能<strong>接口名调</strong>。</p><p><strong>面试答题话术</strong> 「<strong>接口静态方法属于接口本身</strong>，只能接口名调用，实现类<strong>不能继承也不能覆盖</strong>。它的作用就一个：放和接口<strong>强相关的工具或工厂方法</strong>，让接口和它的工厂放在一起，避免再建一个单独的 <strong>Factory 或 Utils 类</strong>。项目里我在协议转换接口上放了 create 这样的<strong>静态工厂</strong>，根据类型返回对应实现，调用方不用知道具体实现类。这也是 <strong>Java 8</strong> 设计者想让接口从纯契约进化成『<strong>契约 + 配套工具</strong>』的体现。对比一下：<strong>default 方法是给实现类『继承』用的，static 方法是给调用方『直接用』的</strong>。」</p><hr><h2 id="_37-stream-的-skip-long-和-limit-long-的区别-★★☆" tabindex="-1">37. Stream 的 skip(long) 和 limit(long) 的区别 ★★☆ <a class="header-anchor" href="#_37-stream-的-skip-long-和-limit-long-的区别-★★☆" aria-label="Permalink to &quot;37. Stream 的 skip(long) 和 limit(long) 的区别 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>skip(n)</strong> 是「<strong>跳过前 n 个元素，取剩下的</strong>」；<strong>limit(n)</strong> 是「<strong>最多取前 n 个，剩下的不要</strong>」。两个都是<strong>中间操作、惰性</strong>的，而且都支持<strong>短路优化</strong>——比如先 limit 再 skip，就不需要遍历所有元素。它们经常配合做<strong>分页</strong>：<code>skip((page-1)*size).limit(size)</code>。</p><p><strong>我的项目关联</strong> 项目里做「<strong>伪分页</strong>」和「<strong>Top N</strong>」时用过：批量下发设备命令时，把一个大列表按每批 <strong>100</strong> 切分，<code>stream.skip(i*100).limit(100)</code>；统计「充电量 Top 10 的场站」用 limit(10)。<strong>通用坑</strong>：<strong>skip 对性能不友好</strong>——它不会跳过计算，只是把前 n 个「丢」掉，数据源很大、跳得很多时，前面 n 个还是会被遍历。所以真正的<strong>数据库分页</strong>我都在 SQL 层用 <strong>MyBatis-Plus 的 Page</strong> 做，绝不用 skip 在内存里给大表分页。</p><p><strong>面试答题话术</strong> 「<strong>skip 是跳过前 n 个</strong>，<strong>limit 是只取前 n 个</strong>，都是<strong>惰性中间操作</strong>，还都支持<strong>短路</strong>。它们组合就是<strong>内存分页</strong>：skip((page-1)*size).limit(size)。但有个点我会主动讲：<strong>skip 不是真的不处理</strong>，前 n 个元素还是会被遍历再丢掉，数据量大、跳得远就慢，所以真分页我在 SQL 层用 Page 做，Stream 的 skip 只用在内存里的小列表切分，比如把批量下发按每批 100 切。」</p><hr><h2 id="_38-hashmap、linkedhashmap、treemap-的区别与选型-★★★" tabindex="-1">38. HashMap、LinkedHashMap、TreeMap 的区别与选型 ★★★ <a class="header-anchor" href="#_38-hashmap、linkedhashmap、treemap-的区别与选型-★★★" aria-label="Permalink to &quot;38. HashMap、LinkedHashMap、TreeMap 的区别与选型 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>HashMap</strong> 是哈希表，<strong>无序</strong>，增删查平均 O(1)（最坏退化到 O(logn)），key 允许一个 null；<strong>LinkedHashMap</strong> 在 HashMap 基础上多一条<strong>双向链表</strong>，维护<strong>插入顺序</strong>（开 accessOrder 就变成访问顺序，能做 <strong>LRU</strong>）；<strong>TreeMap</strong> 是<strong>红黑树</strong>，key 按自然序或 Comparator 排序，操作 O(logn)，key 不允许 null。选型口诀：要快用 HashMap、要顺序用 LinkedHashMap、要排序用 TreeMap。</p><p><strong>我的项目关联</strong> 项目里默认用 <strong>HashMap</strong>——协议命令表、设备会话缓存这种高频读写；需要「<strong>保持插入顺序</strong>」时用 <strong>LinkedHashMap</strong>——按下发顺序展示的批量命令结果、按接收顺序记录报文日志；需要「<strong>按 key 有序</strong>」时用 <strong>TreeMap</strong>——按费率生效时间排序的分时电价配置、按订单时间排序的统计（key 存时间）。<strong>通用坑</strong>：<strong>TreeMap 的 key 不能是 null，会 NPE</strong>；<strong>HashMap 用可变对象当 key 又不重写 hashCode/equals 会 get 不到</strong>。</p><p><strong>面试答题话术</strong> 「三者都是 Map 实现：<strong>HashMap</strong> 是哈希表，O(1)，key 允许一个 null；<strong>LinkedHashMap</strong> 多一条<strong>双向链表</strong>保<strong>插入顺序</strong>，开 accessOrder 还能变访问顺序做 <strong>LRU</strong>；<strong>TreeMap</strong> 是<strong>红黑树</strong>，key 按顺序排，O(logn)，key 不允许 null。选型我按需求来——项目里协议命令表这种高频读写用 HashMap，按顺序展示的批量结果用 LinkedHashMap，分时电价按生效时间排序的配置用 TreeMap。坑就是 <strong>TreeMap 的 null key 会 NPE</strong>，HashMap 用可变对象当 key 会查不到。」</p><hr><h2 id="_39-collection-与-collections-的区别-★★☆" tabindex="-1">39. Collection 与 Collections 的区别 ★★☆ <a class="header-anchor" href="#_39-collection-与-collections-的区别-★★☆" aria-label="Permalink to &quot;39. Collection 与 Collections 的区别 ★★☆&quot;">​</a></h2><p><strong>通俗理解</strong><strong>Collection</strong> 是<strong>接口</strong>，是 <strong>List/Set/Queue 的父接口</strong>，定义集合的<strong>基本能力</strong>（add/remove/size/iterator）。<strong>Collections</strong> 是一个<strong>工具类</strong>（多了个 s），全是<strong>静态方法</strong>，用来操作或包装集合——排序 sort、反转 reverse、打乱 shuffle、求最值 max/min、同步包装 synchronizedXxx、不可变包装 unmodifiableXxx、二分查找 binarySearch。</p><p><strong>我的项目关联</strong> 项目里经常用 <code>Collections.emptyList()</code> 返回<strong>空列表</strong>而不是 null，避免下游<strong>判空</strong>；<code>Collections.synchronizedList</code> 包装过几个需要<strong>多线程写</strong>的列表；<code>Collections.unmodifiableList</code> 用在把内部配置列表暴露出去时防止<strong>外部修改</strong>。<strong>通用坑</strong>：<code>Collections.sort</code> 要求元素<strong>实现 Comparable</strong> 或者传 Comparator，否则抛 <strong>ClassCastException</strong>；空集合场景<strong>别返回 null</strong>，用 emptyList 能让调用方少一层判空。</p><p><strong>面试答题话术</strong> 「一句话：<strong>Collection 是接口，Collections 是工具类</strong>，多一个 s。Collection 是 List、Set、Queue 的<strong>父接口</strong>，定义集合的基本操作；Collections 全是<strong>静态方法</strong>，sort、reverse、shuffle、max/min、synchronizedXxx、unmodifiableXxx、emptyList 这些。项目里我常用 <strong>emptyList 代替返回 null</strong>，用 unmodifiableList <strong>保护内部列表不被外部改</strong>，用 synchronizedList 包装过并发写的列表。坑就是 sort 需要<strong>元素可比</strong>，否则抛 <strong>ClassCastException</strong>。这个考点很低频，但一句话能答出『<strong>接口 vs 工具类</strong>』就是满分。」</p><hr><h2 id="_40-arraylist、linkedlist、vector-的区别-★★★" tabindex="-1">40. ArrayList、LinkedList、Vector 的区别 ★★★ <a class="header-anchor" href="#_40-arraylist、linkedlist、vector-的区别-★★★" aria-label="Permalink to &quot;40. ArrayList、LinkedList、Vector 的区别 ★★★&quot;">​</a></h2><p><strong>通俗理解</strong><strong>ArrayList</strong> 是数组，<strong>随机访问 O(1)</strong>，中间增删 O(n)，扩容 1.5 倍，<strong>线程不安全</strong>；<strong>LinkedList</strong> 是<strong>双向链表</strong>，头尾增删 O(1)，按下标访问要遍历 O(n)，线程不安全，<strong>内存不连续</strong>、吃不到 CPU 缓存，实际很少用；<strong>Vector</strong> 是老古董，和 ArrayList 一样是数组，但所有方法用 <strong>synchronized</strong> 同步，<strong>线程安全却性能差</strong>，扩容默认翻倍。Vector 基本废弃，线程安全要用 <strong>CopyOnWriteArrayList</strong> 或 <strong>Collections.synchronizedList</strong>，或者并发容器。</p><p><strong>我的项目关联</strong> 项目里默认用 <strong>ArrayList</strong> 处理设备列表、订单列表、批量数据；<strong>LinkedList</strong> 几乎不用——遍历性能差、内存不连续，需要「<strong>头尾频繁增删</strong>」的场景我们用的是 <strong>ArrayDeque</strong> 当队列。<strong>Vector</strong> 项目里从没出现过。<strong>通用坑</strong>：ArrayList 遍历中增删会抛 <strong>ConcurrentModificationException</strong>（前面考点讲过，用 removeIf 或 iterator.remove）；<strong>线程安全需求我也不会用 Vector</strong>，而是用 <strong>CopyOnWriteArrayList</strong> 或并发容器。</p><p><strong>面试答题话术</strong> 「<strong>ArrayList 是数组</strong>，<strong>随机访问 O(1)</strong>、中间增删 O(n)、扩容 1.5 倍、<strong>线程不安全</strong>；<strong>LinkedList 是双向链表</strong>，头尾快但随机访问慢、内存不连续，实际几乎不用；<strong>Vector</strong> 是和 ArrayList 一样的数组，但方法全 <strong>synchronized</strong>，<strong>线程安全却性能差</strong>，扩容翻倍，已经废弃。项目里我统一用 ArrayList，需要队列用 <strong>ArrayDeque</strong>，需要线程安全的列表用 <strong>CopyOnWriteArrayList</strong> 或 synchronizedList，绝不用 Vector。这三个里 LinkedList 我基本只在口头上提，实际用不到——它的头尾优势在业务里远没有 ArrayDeque 好用。」</p>',198)]))}const u=t(g,[["render",a]]);export{h as __pageData,u as default};
